import type { ModelUsage } from "claude-code";

export const totalTokens = (u: ModelUsage) =>
	u.input_tokens +
	u.output_tokens +
	u.cache_read_input_tokens +
	u.cache_creation_input_tokens;

// what a turn took in and wrote, leaving out what the prompt cache served
export const newTokens = (u: ModelUsage) =>
	u.input_tokens + u.output_tokens + u.cache_creation_input_tokens;

export const LABEL_MAX = 20;

export const elapsed = (ms: number) => {
	const s = Math.max(0, Math.round(ms / 1000));
	return s < 60
		? `${s}s`
		: `${Math.floor(s / 60)}m${String(s % 60).padStart(2, "0")}s`;
};

export const clip = (s: string) =>
	s.length > LABEL_MAX ? `${s.slice(0, LABEL_MAX - 1)}…` : s;

export const cut = (s: string, n: number) =>
	s.length > n ? `${s.slice(0, n - 1)}…` : s;

export const firstLine = (answer: string) =>
	cut(
		answer
			.split("\n")
			.map((l) =>
				l
					.replace(/^[#>*\-\s]+/, "")
					.replace(/[*`]/g, "")
					.trim(),
			)
			.find((l) => l !== "") ?? "done",
		60,
	);

export const ago = (ms: number) => {
	const s = Math.max(0, Math.round(ms / 1000));
	return s < 60
		? `${s}s`
		: s < 3600
			? `${Math.floor(s / 60)}m`
			: `${Math.floor(s / 3600)}h`;
};

export const kilo = (n: number) =>
	n < 1000 ? `${n}` : `${Math.round(n / 1000)}k`;

export const tail = (s: string, n: number) =>
	s.length > n ? `…${s.slice(s.length - n + 1)}` : s;

export const pathOf = (e: object) => {
	const { file_path, notebook_path } = e as {
		file_path?: unknown;
		notebook_path?: unknown;
	};
	const path = file_path ?? notebook_path;
	return typeof path === "string" ? path : undefined;
};

export const short = (model: string) => model.replace(/^.*claude-/, "");

files.hooks/pane.tsx:
import type { Elements, RenderInput } from "claude-code";
import type {
	AgentRow,
	Alert,
	BackgroundTask,
	FileTouch,
	PullRequest,
	RepoState,
	SessionCron,
	SkillRun,
	TurnMark,
	WorkItem,
} from "../types";
import { hhmm, nextFire } from "./cron";
import { ago, elapsed, kilo, tail } from "./format";
import { isMergeable } from "./pr";
import type { Rain } from "./rain";
import { RAIN, RAIN_ROWS, rainCells, rainMessage } from "./rain";
import { end, isBusy, isLive, isOpenRun } from "./status";
import {
	C,
	CHECKS,
	COLOR,
	GIT_COLOR,
	GLOW,
	ICON,
	modelColor,
	ORDER,
	PANE,
	REVIEW,
	RUN,
	SHOWN,
	SPARK,
	SPINNER,
} from "./theme";

// Everything the pane draws, read by register (only it may touch $).
export type PaneValues = {
	e: RenderInput<"Pane">;
	els: Elements[RenderInput<"Pane">["surface"]];
	t: number;
	root: string | undefined;
	rain: Rain;
	hint: string;
	tabKeys: string;
	onToggle: () => unknown;
	list: AgentRow[];
	runs: SkillRun[];
	work: WorkItem[];
	touched: FileTouch[];
	uncommitted: number;
	git: RepoState;
	pr: PullRequest | null;
	warnings: Alert[];
	tag: string;
	since: number;
	bg: BackgroundTask[];
	scheduled: SessionCron[];
	marks: TurnMark[];
};

export const paneView = ({
	e,
	els,
	t,
	root,
	rain,
	hint,
	tabKeys,
	onToggle,
	list,
	runs,
	work,
	touched,
	uncommitted,
	git,
	pr,
	warnings,
	tag,
	since,
	bg,
	scheduled,
	marks,
}: PaneValues) => {
	const { Box, Button, Link, Text } = els;
	const frame = Math.floor(t / 100);
	const spin = SPINNER[frame % SPINNER.length];
	const busy = isBusy(list, runs, work);
	const glow = busy ? (GLOW[frame % GLOW.length] ?? C.mauve) : C.mauve;
	const width = Math.max(30, e.props.bodyColumns);
	const rule = width - 2;
	const at = busy ? (frame % (rule + 6)) - 3 : -3;
	const lit = [at, at + 3].map((n) => Math.min(rule, Math.max(0, n))) as [
		number,
		number,
	];
	const spark = marks.slice(-(width - 4));
	const longest = Math.max(1, ...spark.map((m) => m.ms));
	// live agents first, then background work, crons and the latest finished,
	// drawn in that order
	const finished = list.filter((a) => !isLive(a)).reverse();
	const keep = new Set<AgentRow | BackgroundTask | SessionCron>(
		[...list.filter(isLive), ...bg, ...scheduled, ...finished].slice(0, SHOWN),
	);
	const liveShown = list.filter((a) => isLive(a) && keep.has(a));
	const doneShown = finished.filter((a) => keep.has(a));
	const shown = [...liveShown, ...doneShown];
	const bgShown = bg.filter((b) => keep.has(b));
	const cronsShown = scheduled.filter((c) => keep.has(c));
	const more = list.length + bg.length + scheduled.length - keep.size;
	const labelWidth = Math.max(
		0,
		...shown.map((a) => a.label.length),
		...bgShown.map((b) => b.type.length),
	);
	const modelWidth = Math.max(0, ...shown.map((a) => a.model.length));
	const pathWidth = width - 4 - 3 - 4;
	const shortPath = (p: string) =>
		root !== undefined && p.startsWith(`${root}/`)
			? p.slice(root.length + 1)
			: p;
	const counts = ORDER.map(
		(s) => [s, list.filter((a) => a.status === s).length] as const,
	);
	if ("Raster" in els) {
		rain.columns = width;
	}
	// docked, the pane fills its height so the rain sits on the bottom edge;
	// inline, the frame fits the tree and would grow to bodyRows instead
	const floor =
		e.props.placement === "dock" ? e.props.scroll.bodyRows : undefined;
	const skill = runs.at(-1);
	const agentsRunning = list.filter((a) => a.status === "running").length;
	// what keeps Claude busy, one mark each, in the colors of their boxes
	const status = [
		...(since > 0
			? [{ color: C.peach, text: `⏳ working ${elapsed(t - since)}` }]
			: []),
		...(isOpenRun(skill) && skill !== undefined
			? [
					{
						color: C.blue,
						text: `🔧 ${skill.skills.join(", ")} ${elapsed(t - skill.startedAt)}`,
					},
				]
			: []),
		...(agentsRunning > 0
			? [
					{
						color: C.mauve,
						text: `🤖 ${agentsRunning} agent${agentsRunning === 1 ? "" : "s"}`,
					},
				]
			: []),
		...(work.some((w) => w.text === undefined)
			? [{ color: C.green, text: "📝 summarizing" }]
			: []),
	];
	const agentRow = (a: AgentRow) => (
		<Text wrap="truncate-end">
			<Text color={COLOR[a.status]}>
				{a.status === "running" ? spin : ICON[a.status]}
			</Text>{" "}
			<Text color={C.text} dimColor={a.status !== "running"}>
				{a.label.padEnd(labelWidth)}
			</Text>{" "}
			<Text color={modelColor(a.model)} dimColor={a.status !== "running"}>
				{a.model.padEnd(modelWidth)}
			</Text>{" "}
			<Text color={C.overlay} dimColor={a.status !== "running"}>
				{elapsed(end(a, t) - a.startedAt).padStart(6)}
			</Text>{" "}
			<Text color={C.subtext} dimColor>
				{a.description}
				{a.status === "running" && a.tool !== undefined ? ` · ${a.tool}` : ""}
			</Text>
		</Text>
	);
	// a PR read for the branch before a checkout is not this one's
	const pull = pr !== null && pr.branch === git.branch ? pr : undefined;
	const prMarks =
		pull === undefined
			? []
			: [
					...(pull.isDraft ? [{ color: C.overlay, text: "✎ draft" }] : []),
					REVIEW[pull.review],
					...(pull.ci === undefined ? [] : [CHECKS[pull.ci]]),
					...(pull.unresolved > 0
						? [{ color: C.peach, text: `💬 ${pull.unresolved} unresolved` }]
						: []),
				];
	const keycap = (k: string) => (
		<Text backgroundColor={C.surface0} color={C.lavender}>{` ${k} `}</Text>
	);

	return (
		<Box
			flexDirection="column"
			width={width}
			{...(floor === undefined ? {} : { minHeight: floor })}
		>
			<Box paddingX={1} justifyContent="space-between">
				<Box gap={2}>
					<Text bold color={glow}>
						SUMMARY
					</Text>
					{status.length > 0 && (
						<Text wrap="truncate-end">
							{status.map((m, i) => (
								<Text color={m.color}>{`${i > 0 ? "  " : ""}${m.text}`}</Text>
							))}
						</Text>
					)}
				</Box>
				<Text color={modelColor(tag)}>{tag}</Text>
			</Box>
			<Box paddingX={1}>
				<Text>
					<Text color={C.surface0}>{"━".repeat(lit[0])}</Text>
					<Text color={C.lavender}>{"━".repeat(lit[1] - lit[0])}</Text>
					<Text color={C.surface0}>{"━".repeat(rule - lit[1])}</Text>
				</Text>
			</Box>
			{warnings.length > 0 && (
				<Box
					flexDirection="column"
					borderStyle="round"
					borderColor={C.red}
					paddingX={1}
				>
					<Text bold color={C.red}>
						alerts
					</Text>
					{warnings.map((a) => (
						<Text wrap="truncate-end">
							<Text color={C.red}>✗</Text>{" "}
							<Text color={C.overlay}>{`${ago(t - a.at)} ago`.padEnd(7)}</Text>{" "}
							<Text color={C.peach}>{a.tool}</Text>
							{a.agent !== undefined && (
								<Text color={C.overlay}>{` @${a.agent}`}</Text>
							)}
							<Text color={C.subtext}>{`  ${a.reason}`}</Text>
						</Text>
					))}
				</Box>
			)}
			<Box
				flexDirection="column"
				borderStyle="round"
				borderColor={C.green}
				paddingX={1}
			>
				<Text bold color={C.green}>
					recent
				</Text>
				{work.length === 0 && (
					<Text color={C.overlay}>no finished work yet</Text>
				)}
				{work.map((w, i) => (
					<Box flexDirection="column">
						<Box gap={1}>
							{w.text === undefined ? (
								<Text color={C.peach}>{spin}</Text>
							) : (
								<Text color={C.green}>✓</Text>
							)}
							<Text
								bold={i === 0}
								dimColor={i > 0}
								color={w.text === undefined ? C.subtext : C.text}
							>
								{w.text ?? "summarizing…"}
							</Text>
						</Box>
						<Box paddingLeft={2}>
							<Text color={C.overlay} dimColor>
								{[
									`${ago(t - w.at)} ago`,
									elapsed(w.durationMs),
									...(w.tokens === undefined ? [] : [kilo(w.tokens)]),
								].join(" · ")}
							</Text>
						</Box>
					</Box>
				))}
			</Box>
			<Box
				flexDirection="column"
				borderStyle="round"
				borderColor={C.surface1}
				paddingX={1}
			>
				<Text>
					<Text bold color={C.mauve}>
						{"agents & jobs"}
					</Text>
					{counts
						.filter(([, n]) => n > 0)
						.map(([s, n]) => (
							<Text color={COLOR[s]}>{`  ${ICON[s]} ${n} ${s}`}</Text>
						))}
					{bg.length > 0 && <Text color={C.sky}>{`  ${bg.length} bg`}</Text>}
					{scheduled.length > 0 && (
						<Text color={C.lavender}>{`  ${scheduled.length} scheduled`}</Text>
					)}
				</Text>
				{list.length + bg.length + scheduled.length === 0 && (
					<Text color={C.overlay}>nothing running or scheduled</Text>
				)}
				{liveShown.map(agentRow)}
				{bgShown.map((b) => (
					<Text wrap="truncate-end">
						<Text color={b.status === "running" ? C.yellow : C.overlay}>
							{b.status === "running" ? "●" : "○"}
						</Text>{" "}
						<Text color={C.sky}>{b.type.padEnd(labelWidth)}</Text>{" "}
						<Text color={C.subtext}>{b.label}</Text>
					</Text>
				))}
				{cronsShown.map((c) => {
					const at = nextFire(c.schedule, t);
					return (
						<Text wrap="truncate-end">
							<Text color={C.lavender}>{c.recurring ? "↻" : "◷"}</Text>{" "}
							<Text color={C.text}>
								{at === undefined
									? c.schedule
									: `${hhmm(at, t)} in ${ago(at - t)}`}
							</Text>{" "}
							<Text color={C.subtext}>{c.prompt}</Text>
						</Text>
					);
				})}
				{doneShown.map(agentRow)}
				{more > 0 && <Text color={C.overlay}>{`+${more} more`}</Text>}
			</Box>
			<Box
				flexDirection="column"
				borderStyle="round"
				borderColor={C.surface1}
				paddingX={1}
			>
				<Text>
					<Text bold color={C.yellow}>
						files
					</Text>
					<Text color={C.overlay}>
						{`  ${touched.length} edited · ${uncommitted} uncommitted`}
					</Text>
				</Text>
				{touched.length === 0 && (
					<Text color={C.overlay}>no file edited yet</Text>
				)}
				{touched.slice(0, SHOWN).map((f) => (
					<Text>
						<Text
							color={
								f.status === undefined
									? C.overlay
									: (GIT_COLOR[f.status] ?? C.peach)
							}
						>
							{(f.status ?? "·").padEnd(2)}
						</Text>{" "}
						<Text color={C.overlay}>
							{(f.edits > 0 ? `${f.edits}×` : "·").padStart(3)}
						</Text>{" "}
						<Text color={C.text}>{tail(shortPath(f.path), pathWidth)}</Text>
					</Text>
				))}
				{touched.length > SHOWN && (
					<Text color={C.overlay}>{`+${touched.length - SHOWN} more`}</Text>
				)}
			</Box>
			<Box
				flexDirection="column"
				borderStyle="round"
				borderColor={C.surface1}
				paddingX={1}
			>
				<Text>
					<Text bold color={C.peach}>
						git
					</Text>
					<Text color={C.overlay}>
						{root === undefined
							? "  not a repository"
							: `  ${git.branch ?? "?"}${
									git.upstream === undefined
										? ` (no upstream) · ${uncommitted} uncommitted`
										: ` → ${git.upstream} · ${uncommitted} uncommitted · ↑${git.ahead} ↓${git.behind}`
								}`}
					</Text>
				</Text>
				{pull !== undefined && (
					<Text wrap="truncate-end">
						<Text color={C.lavender}>{`PR #${pull.number}`}</Text>
						{prMarks.map((m, i) => (
							<Text color={m.color}>{`${i === 0 ? " " : " · "}${m.text}`}</Text>
						))}
					</Text>
				)}
				{pull !== undefined && isMergeable(pull) && (
					<Box flexDirection="column" paddingLeft={2}>
						<Text color={C.green} wrap="truncate-end">
							⇢ ready: merge it in the web UI
						</Text>
						<Text color={C.blue}>
							<Link href={pull.url} />
						</Text>
					</Box>
				)}
				{git.commits.length === 0 && (
					<Text color={C.overlay}>no commit yet</Text>
				)}
				{git.commits.map((c, i) => (
					<Text wrap="truncate-end">
						{git.upstream === undefined ? (
							<Text color={C.overlay}>·</Text>
						) : i < git.ahead ? (
							<Text color={C.yellow}>↑</Text>
						) : (
							<Text color={C.green}>✓</Text>
						)}{" "}
						<Text color={C.overlay}>{c.hash}</Text>{" "}
						<Text color={C.overlay} dimColor>
							{ago(t - c.at).padStart(3)}
						</Text>{" "}
						<Text color={i < git.ahead ? C.text : C.subtext}>{c.subject}</Text>
					</Text>
				))}
			</Box>
			<Box
				flexDirection="column"
				borderStyle="round"
				borderColor={C.surface1}
				paddingX={1}
			>
				<Text bold color={C.blue}>
					skills
				</Text>
				{runs.length === 0 ? (
					<Text color={C.overlay}>no skill yet</Text>
				) : (
					[...runs].reverse().map((r) => (
						<Text wrap="truncate-end">
							{r.result === undefined ? (
								<Text color={C.peach}>{spin}</Text>
							) : (
								<Text color={RUN[r.result].color}>{RUN[r.result].icon}</Text>
							)}{" "}
							<Text
								bold={r.result === undefined}
								color={r.result === undefined ? C.text : C.subtext}
							>
								{r.skills.join(", ")}
							</Text>{" "}
							<Text color={modelColor(r.model)}>
								{[r.model, r.effort].filter((v) => v !== undefined).join(" · ")}
							</Text>{" "}
							<Text color={C.overlay}>
								{elapsed((r.endedAt ?? t) - r.startedAt)}
							</Text>
						</Text>
					))
				)}
			</Box>
			<Box
				flexDirection="column"
				borderStyle="round"
				borderColor={C.surface1}
				paddingX={1}
			>
				<Text>
					<Text bold color={C.sky}>
						turn time
					</Text>
					{marks.length > 0 && (
						<Text color={C.overlay}>
							{`  ${marks.length} turn${marks.length === 1 ? "" : "s"} · avg ${elapsed(
								marks.reduce((n, m) => n + m.ms, 0) / marks.length,
							)} · max ${elapsed(Math.max(...marks.map((m) => m.ms)))}`}
						</Text>
					)}
				</Text>
				{spark.length === 0 ? (
					<Text color={C.overlay}>no turn yet</Text>
				) : (
					<Text>
						{spark.map((m) => (
							<Text color={m.ok ? C.green : C.red}>
								{SPARK[Math.max(0, Math.ceil((m.ms / longest) * 8) - 1)]}
							</Text>
						))}
					</Text>
				)}
			</Box>
			<Box paddingX={1} columnGap={2} flexWrap="wrap">
				<Button plain key="toggle" onPress={onToggle}>
					{keycap(hint)}
					<Text color={C.subtext}> close</Text>
				</Button>
				<Text>
					{keycap("ctrl+x tab")}
					<Text color={C.subtext}> focus</Text>
				</Text>
				{tabKeys !== "" && (
					<Text>
						{keycap(tabKeys)}
						<Text color={C.subtext}> tabs</Text>
					</Text>
				)}
				{keycap(`/${PANE} help`)}
			</Box>
			<Box flexGrow={1} />
			{"Raster" in els && (
				<els.Raster
					key={RAIN}
					columns={width}
					rows={RAIN_ROWS}
					cells={rainCells(
						rain.t,
						width,
						RAIN_ROWS,
						rain.pace === 0 ? rainMessage(width, rain.idleSince, t) : undefined,
					)}
				/>
			)}
		</Box>
	);
};

